import sys


def slow(data):
    sums = {}
    for line in data.split(b"\n")[1:]:
        if not line:
            continue
        parts = line.rstrip(b"\r").split(b",")
        if len(parts) < 3:
            continue
        try:
            v = float(parts[2])
        except ValueError:
            continue
        cat = parts[1]
        sums[cat] = sums.get(cat, 0.0) + v
    return sums


def fast(data):
    t = data.replace(b"\r\n", b"\n").replace(b"\n", b",").split(b",")
    if t and t[-1] == b"":
        t.pop()
    body = t[3:]
    if len(body) % 3 != 0:
        return None
    sums = {}
    get = sums.get
    try:
        for c, v in zip(body[1::3], body[2::3]):
            sums[c] = get(c, 0.0) + float(v)
    except ValueError:
        return None
    return sums


def main():
    data = sys.stdin.buffer.read()
    sums = fast(data)
    if sums is None:
        sums = slow(data)
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + "," + ("%.2f" % sums[cat]))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()
